def need(condition, message):
    if not condition:
        raise ValueError(message)

def raw9(info):
    return [getattr(info, key, None) for key in (
        "st_dev", "st_ino", "st_size", "st_mtime_ns", "st_ctime_ns", "st_mode", "st_nlink",
        "st_file_attributes", "st_birthtime_ns")]

def ordinary_chain(path, *, file=False):
    path = absolute(path)
    for item in (*reversed(path.parents), path):
        if os.path.lexists(item):
            info = item.lstat()
            need(not stat.S_ISLNK(info.st_mode) and
                 not (getattr(info, "st_file_attributes", 0) & 0x400), f"no symlink/reparse path: {item}")
            if item != path:
                need(stat.S_ISDIR(info.st_mode), f"ordinary directory ancestor: {item}")
    if file:
        info = path.lstat()
        need(stat.S_ISREG(info.st_mode) and info.st_nlink == 1, f"ordinary single-link Source file: {path}")
    return path

def pairs(items):
    result = {}
    for key, value in items:
        need(key not in result, f"duplicate JSON key: {key}")
        result[key] = value
    return result

def decode(data):
    return json.loads(data.decode("utf-8", errors="strict"), object_pairs_hook=pairs,
                      parse_constant=lambda token: (_ for _ in ()).throw(ValueError(token)))

def fact3(pin):
    need(isinstance(pin, dict) and all(key in pin for key in ("path", "sha256", "bytes")), "actual fact3 pin")
    need(type(pin["path"]) is str and type(pin["sha256"]) is str and
         re.fullmatch(r"[0-9a-f]{64}", pin["sha256"]) is not None and
         type(pin["bytes"]) is int and 0 <= pin["bytes"] <= 8388608, "fact3 path/hash/exact length types")
    return {key: pin[key] for key in ("path", "sha256", "bytes")}

def _contains_pin(value, selected):
    if isinstance(value, dict):
        if all(key in value for key in ("path", "sha256", "bytes")):
            if {key:value[key] for key in ("path", "sha256", "bytes")} == fact3(selected):
                return True
        return any(_contains_pin(item, selected) for item in value.values())
    return isinstance(value, list) and any(_contains_pin(item, selected) for item in value)

def exact_fact3(pin):
    need(type(pin) is dict and set(pin) == {"path", "sha256", "bytes"}, "closed exact Root Source fact3")
    need(type(pin["path"]) is str and str(absolute(pin["path"])) == pin["path"] and
         type(pin["sha256"]) is str and re.fullmatch("[a-f0-9]{64}", pin["sha256"]) is not None and
         type(pin["bytes"]) is int and 0 <= pin["bytes"] <= 2097152, "typed exact finite Source fact3")
    return dict(pin)

def exact_pin_occurs(value, pin):
    if type(value) is dict:
        if all(key in value and type(value[key]) is type(pin[key]) and value[key] == pin[key] for key in pin):
            return True
        return any(exact_pin_occurs(child, pin) for child in value.values())
    return type(value) is list and any(exact_pin_occurs(child, pin) for child in value)

def strict_source_decode(body):
    def reject(token):
        raise ValueError('non-integer Source JSON numeric token forbidden: '+token)
    return json.loads(body.decode('utf-8', errors='strict'), object_pairs_hook=pairs,
                      parse_float=reject, parse_constant=reject)
